--- a/src/retry.mjs
+++ b/src/retry.mjs
@@ -1,4 +1,26 @@
 export async function retry(operation, options = {}) {
-  // TODO: implement the contract documented in README.md
-  return operation();
+  const attempts = options.attempts ?? 3;
+  if (!Number.isInteger(attempts) || attempts <= 0) {
+    throw new Error('attempts must be a positive integer');
+  }
+
+  const shouldRetry = options.shouldRetry ?? (() => true);
+  const delayFn = options.delay ?? (() => 0);
+
+  let lastError;
+
+  for (let attempt = 1; attempt <= attempts; attempt++) {
+    try {
+      return await operation();
+    } catch (error) {
+      lastError = error;
+      if (attempt === attempts) {
+        throw lastError;
+      }
+      if (!shouldRetry(error, attempt)) {
+        throw lastError;
+      }
+      await delayFn(attempt, error);
+    }
+  }
 }

diff --git a/src/retry.mjs b/src/retry.mjs
index e6d1fbc..1c55ca7 100644
--- a/src/retry.mjs
+++ b/src/retry.mjs
@@ -1,4 +1,27 @@
 export async function retry(operation, options = {}) {
-  // TODO: implement the contract documented in README.md
-  return operation();
+  const {
+    attempts = 3,
+    shouldRetry = () => true,
+    delay = async () => {},
+  } = options;
+
+  if (!Number.isInteger(attempts) || attempts < 1) {
+    throw new Error('attempts must be a positive integer');
+  }
+
+  let lastError;
+  for (let attempt = 1; attempt <= attempts; attempt++) {
+    try {
+      return await operation();
+    } catch (error) {
+      lastError = error;
+      const canRetry = attempt < attempts && shouldRetry(error, attempt);
+      if (!canRetry) {
+        throw error;
+      }
+      await delay(attempt, error);
+    }
+  }
+
+  throw lastError;
 }

diff --git a/src/ranker.mjs b/src/ranker.mjs
index 65a7daa..dc83001 100644
--- a/src/ranker.mjs
+++ b/src/ranker.mjs
@@ -1,3 +1,34 @@
 export function rankRoutes(routes, context = {}) {
-  return routes;
+  const contextTags = context.tags ?? [];
+  const maxCost = context.maxCost ?? Infinity;
+
+  const scored = [];
+
+  for (const route of routes) {
+    const cost = route.cost ?? 0;
+    if (cost > maxCost) continue;
+
+    const tags = route.tags ?? [];
+    const successRate = route.successRate ?? 0;
+    const latencyMs = route.latencyMs ?? 1000;
+
+    let overlap = 0;
+    for (const tag of tags) {
+      if (contextTags.includes(tag)) overlap++;
+    }
+
+    const score =
+      overlap * 4 + successRate * 3 - Math.log1p(latencyMs) / 5 - cost;
+
+    scored.push({ ...route, score });
+  }
+
+  scored.sort((a, b) => {
+    if (b.score !== a.score) return b.score - a.score;
+    if (a.id < b.id) return -1;
+    if (a.id > b.id) return 1;
+    return 0;
+  });
+
+  return scored;
 }

diff --git a/src/ranker.mjs b/src/ranker.mjs
index 65a7daa..3f916db 100644
--- a/src/ranker.mjs
+++ b/src/ranker.mjs
@@ -1,3 +1,25 @@
 export function rankRoutes(routes, context = {}) {
-  return routes;
+  const ctxTags = Array.isArray(context.tags) ? context.tags : [];
+  const maxCost = context.maxCost === undefined ? Infinity : context.maxCost;
+
+  const scored = routes
+    .filter(r => (r.cost ?? 0) <= maxCost)
+    .map(r => {
+      const routeTags = Array.isArray(r.tags) ? r.tags : [];
+      const tagOverlap = ctxTags.filter(t => routeTags.includes(t)).length;
+      const successRate = typeof r.successRate === 'number' ? r.successRate : 0;
+      const latencyMs = typeof r.latencyMs === 'number' ? r.latencyMs : 1000;
+      const cost = typeof r.cost === 'number' ? r.cost : 0;
+
+      const score = tagOverlap * 4 + successRate * 3 - Math.log1p(latencyMs) / 5 - cost;
+
+      return { ...r, score };
+    });
+
+  scored.sort((a, b) => {
+    if (b.score !== a.score) return b.score - a.score;
+    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
+  });
+
+  return scored;
 }

diff --git a/src/redact.mjs b/src/redact.mjs
index 991c969..3c6e6d8 100644
--- a/src/redact.mjs
+++ b/src/redact.mjs
@@ -1,10 +1,50 @@
 const SECRET_KEY = /token|secret|password|api[-_]?key/i;

+function isPlainObject(value) {
+  if (typeof value !== 'object' || value === null) return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
 export function redactSecrets(value) {
-  if (!value || typeof value !== 'object') return value;
-  const output = Array.isArray(value) ? [] : {};
-  for (const [key, child] of Object.entries(value)) {
-    output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : child;
+  const seen = new WeakMap();
+
+  function transform(val) {
+    if (val === null || typeof val !== 'object') return val;
+
+    // Preserve Date instances without recursing into them
+    if (val instanceof Date) return val;
+
+    // Handle cycles and shared references
+    if (seen.has(val)) return seen.get(val);
+
+    if (Array.isArray(val)) {
+      const copy = [];
+      seen.set(val, copy);
+      for (let i = 0; i < val.length; i++) {
+        copy[i] = transform(val[i]);
+      }
+      return copy;
+    }
+
+    if (isPlainObject(val)) {
+      const copy = {};
+      seen.set(val, copy);
+      const descriptors = Object.getOwnPropertyDescriptors(val);
+      for (const key of Object.keys(descriptors)) {
+        const desc = descriptors[key];
+        // Omit accessor properties (getters/setters) — never invoke them
+        if ('get' in desc || 'set' in desc) continue;
+        // Copy only enumerable data properties
+        if (!desc.enumerable) continue;
+        copy[key] = SECRET_KEY.test(key) ? '[REDACTED]' : transform(desc.value);
+      }
+      return copy;
+    }
+
+    // Non-plain objects (RegExp, Map, Set, etc.) are returned by reference
+    return val;
   }
-  return output;
+
+  return transform(value);
 }

diff --git a/src/redact.mjs b/src/redact.mjs
index 991c969..0c50b5b 100644
--- a/src/redact.mjs
+++ b/src/redact.mjs
@@ -1,10 +1,53 @@
 const SECRET_KEY = /token|secret|password|api[-_]?key/i;

+function isPlainObject(value) {
+  if (value === null || typeof value !== 'object') return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+function isDataDescriptor(desc) {
+  return desc != null && !('get' in desc) && !('set' in desc);
+}
+
+/**
+ * Non-mutating deep transform: redact secret-keyed values.
+ * - Redacts when key contains token|secret|password|api_key|api-key|apikey (case-insensitive)
+ * - Walks nested plain objects and arrays
+ * - Preserves Date instances and primitives
+ * - Preserves shared references; supports cycles
+ * - Does not invoke getters; omits accessor properties
+ */
 export function redactSecrets(value) {
-  if (!value || typeof value !== 'object') return value;
-  const output = Array.isArray(value) ? [] : {};
-  for (const [key, child] of Object.entries(value)) {
-    output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : child;
+  const seen = new WeakMap();
+
+  function walk(node) {
+    if (node === null || typeof node !== 'object') return node;
+    if (node instanceof Date) return node;
+    if (!Array.isArray(node) && !isPlainObject(node)) return node;
+
+    if (seen.has(node)) return seen.get(node);
+
+    if (Array.isArray(node)) {
+      const output = [];
+      seen.set(node, output);
+      for (const key of Object.keys(node)) {
+        const desc = Object.getOwnPropertyDescriptor(node, key);
+        if (!isDataDescriptor(desc) || !desc.enumerable) continue;
+        output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : walk(desc.value);
+      }
+      return output;
+    }
+
+    const output = {};
+    seen.set(node, output);
+    for (const key of Object.keys(node)) {
+      const desc = Object.getOwnPropertyDescriptor(node, key);
+      if (!isDataDescriptor(desc) || !desc.enumerable) continue;
+      output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : walk(desc.value);
+    }
+    return output;
   }
-  return output;
+
+  return walk(value);
 }
